import csv, json

def position_accuracy(gold, picked):
    """
    This function calculates the position accuracy of the picked order against the gold order. It computes the fraction of sentences that are in the correct position.

    @param 
        gold: A list of sentences representing the correct order.
        picked: A list of sentences representing the order picked by the annotator.
    @return: A float representing the fraction of sentences that are in the correct position. If the gold list is empty, it returns 0.0.
    """
    if not gold:
        return 0.0
    correct_pos = sum(g == p for g, p in zip(gold, picked))
    return correct_pos / len(gold)


def evaluate(path):
    """
    This function reads a CSV file containing annotations and evaluates the accuracy of the picked order against the gold order. It returns a list of dictionaries containing the annotation details, the gold order, the picked order, and the position accuracy.
    
    @param path: The path to the CSV file containing the annotations.
    @return: rows: A list of dictionaries, each containing the annotation_id, annotator, storyid, storytitle, lead_time, gold order, picked order, a boolean indicating if the picked order is correct, and the position accuracy.
    """
    rows = []
    with open(path, newline="") as file:
        reader = csv.DictReader(file)
        for row in reader:
            gold = json.loads(row["correct_order"])
            raw_order = json.loads(row["order"])
            picked = raw_order[0]["ranker"]["order"]

            rows.append({
                "annotation_id": row.get("annotation_id"),
                "annotator": row.get("annotator", "unknown"),
                "storyid": row.get("storyid"),
                "storytitle": row.get("storytitle"),
                "lead_time": row.get("lead_time"),
                "gold": gold,
                "picked": picked,
                "correct": gold == picked,  
                "pos_acc": position_accuracy(gold, picked),
            })
    return rows

def report(rows):
    """
    This function generates a report based on the evaluated annotations. It calculates the total number of annotations, the average position accuracy, and the number of fully correct orders. It also lists any annotations that are not fully correct, along with their position accuracy and the gold and picked orders.

    @param rows: A list of dictionaries containing the annotation details, gold order, picked order, correctness, and position accuracy.
    """
    total = len(rows)

    accuracy = sum(r["pos_acc"] for r in rows) / total if total else 0

    # For reference only: exact match accuracy
    exact = sum(r["correct"] for r in rows)
    exact_acc = exact / total if total else 0

    print(f"Total Annotation: {total}")
    print(f"Accuracy (avg. fraction of sentences at correct position): {accuracy:.2%}")
    print(f"Fully correct orders: {exact} ({exact_acc:.2%})")
    print()
    print("Not fully correct:")
    for r in rows:
        if not r["correct"]:
            print(f"- {r['storytitle']} (id {r['storyid']}) - {r['pos_acc']:.0%} in correct position")
            print(f"    gold:   {r['gold']}")
            print(f"    picked: {r['picked']}")


